          active_lease_token_hash = NEW.lease_token_hash,
          active_lease_expires_at = NEW.lease_expires_at,
          active_write_marker = NEW.write_marker,
          active_write_started_at = NULL,
          started_at = NEW.started_at,
          finished_at = NULL,
          error_code = '',
          recovery_state = 'in_progress',
