def install_t021_guards(apps, schema_editor):
    vendor = schema_editor.connection.vendor
    if vendor not in {"sqlite", "postgresql"}:
        raise RuntimeError(f"T021 database guards do not support {vendor}")
    statements = SQLITE_GUARD_SQL if vendor == "sqlite" else POSTGRES_GUARD_SQL
    with schema_editor.connection.cursor() as cursor:
        for statement in statements:
            cursor.execute(statement)
        cursor.execute(
            "UPDATE publishing_publicationattempt "
            "SET state = state WHERE state = 'running'"
        )
        cursor.execute(
            "UPDATE publishing_publicationreconcilegeneration "
            "SET state = state WHERE state = 'running'"
        )
        cursor.execute(
            """
            SELECT COUNT(*)
            FROM publishing_publicationreconciledeliveryobservation delivery
            JOIN publishing_publicationreconcilegeneration generation
              ON generation.id = delivery.reconcile_generation_id
            WHERE delivery.state = 'active'
              AND (
                generation.state <> 'running'
                OR delivery.consumer_name <> generation.consumer_name
                OR delivery.consumer_lease_generation <> generation.consumer_lease_generation
                OR delivery.consumer_lease_token <> generation.consumer_lease_token
                OR delivery.lease_token_hash <> generation.lease_token_hash
                OR delivery.lease_expires_at <> generation.lease_expires_at
              )
            """
        )
        if cursor.fetchone()[0]:
            raise RuntimeError(
                "T021 migration found an orphan reconcile delivery observation"
            )


def remove_t021_guards(apps, schema_editor):
    vendor = schema_editor.connection.vendor
    with schema_editor.connection.cursor() as cursor:
        if vendor == "sqlite":
            for name in SQLITE_TRIGGER_NAMES:
                cursor.execute(f'DROP TRIGGER IF EXISTS "{name}"')
        elif vendor == "postgresql":
            for name, table in POSTGRES_TRIGGER_TABLES.items():
                cursor.execute(
                    f'DROP TRIGGER IF EXISTS "{name}" ON "{table}"'
                )
            for name in POSTGRES_FUNCTION_NAMES:
                cursor.execute(f'DROP FUNCTION IF EXISTS "{name}"()')
        else:
            raise RuntimeError(f"T021 database guards do not support {vendor}")


def reject_populated_reverse(apps, schema_editor):
    models_to_check = (
        apps.get_model("publishing", "PublicationAttempt"),
        apps.get_model("publishing", "PublicationExecutionObservation"),
        apps.get_model("publishing", "PublicationReconcileGeneration"),
        apps.get_model(
            "publishing", "PublicationReconcileDeliveryObservation"
        ),
        apps.get_model("publishing", "PublicationLateExecutionResult"),
    )
    if any(
        model.objects.using(schema_editor.connection.alias).exists()
        for model in models_to_check
    ):
        raise IrreversibleError(
            "T021 publication execution fencing cannot be reversed while publication rows exist"
        )


